  'rb.set.testingMode': 'Testing Mode',
  'rb.set.newFeature': 'New feature',
  'rb.set.newFeatureTesting': 'New feature: Testing Mode',
  'rb.set.testPromo': 'Put your memory to the test — the app quizzes you on verses from anywhere in the Quran, so you find the weak spots before they find you.',
  'rb.set.testYourself': 'TEST YOURSELF',
  'rb.set.experiences': 'Experiences',
  'rb.set.sounds': 'Sounds & Haptics',
  'rb.set.notifications': 'Notifications',
  'rb.set.downloads': 'Downloads',
