  // Parity repair (2026-11-24): hardcoded-English strings converted to translated keys (i18n pass Part A).
  'chal.howItWorks': 'How it works: create a challenge and share its link. When a member opens your link, your progress joins their view — and when they share their link back, their progress joins yours. No accounts, no server, nothing uploaded.',
  'chal.leagueFootnote': 'Leagues run on the same no-account group challenges above: create a challenge, share its link, and your group’s progress is the leaderboard. No prizes are promised here — points and places are the reward.',
  'chal.leagueIntro': 'A time-boxed race to goodness: join a League, set a memorisation goal (for example 80 pages in 80 days, one page a day), get a daily plan until the deadline, and earn points by reciting or revising. Points move you up the leaderboard.',
  'chal.ramadanIntro': 'Each Ramadan: read or recite 90% or more of the Quran during the month, and a physical mushaf is donated on your behalf to a Muslim in need. One per person. Free to join.',
  'chal.ramadanProgressLabel': 'Ramadan challenge progress',
  'chal.ramadanProgressNote': 'Reading, listening and recitation all count; off-platform sessions logged on My Progress count too. Your live percentage appears here once Ramadan begins — at 90% you get an in-app confirmation that a mushaf will be donated on your behalf.',
  'chal.tplBaqarahGoal': '48 pages in 48 days',
  'chal.tplBaqarahName': 'Surah Al-Baqarah Challenge',
  'chal.tplBaqarahNote': 'The longest surah, one page a day',
