  'chal.tplRamadanNote': 'One page a day until Ramadan',
  'coach.attributionNote': 'Quran text, translation and audio via Quran.com. Your recitation audio never leaves your device unless you choose to share it with your teacher. A teacher is still needed for tajweed — this tool checks words, not tajweed.',
  'coach.couldNotFollow': 'We heard your voice, but the checker could not follow the words. Try holding the phone a little closer, reciting a little louder and slower, and giving it a second to start listening before the first word — then try again.',
  'coach.extraSkippedTitle': 'Extra words & skipped passages',
  'coach.extraWordHere': 'Extra word heard near here',
  'coach.followAlongNote': 'Follow-along: recite with the text visible and the app highlights each word as you say it. Nothing is judged, nothing is logged as a mistake.',
  'coach.introRecite': 'Listen, hide the verse, then recite it aloud. The checker follows your recitation word by word, on this device.',
  'coach.listenBackNotSaved': 'Recorded on this device only. It stays here unless you choose to share or download it below — the app never uploads it, and it is not saved past this browser session. Turn on “{setting}” in {settings} to keep recordings for later.',
  'coach.listenBackSaved': 'Recorded on this device only, and saved on this device so you can listen back to it later from your session history. It stays here unless you choose to share or download it below — the app never uploads it.',
  'coach.micCheckLink': 'microphone check',
  'coach.micExplain': 'We need the microphone to hear your recitation. Audio is processed on your device and never uploaded. Sharing a recording with your teacher is always your choice, after the session — nothing is sent automatically.',
