  'rb.set.account': 'الحساب',
  'rb.set.noPush': 'على الجهاز فقط — لا إشعارات فورية',
  'rb.set.noPushNote': 'The app works fully without an account, so it cannot send push notifications. Your daily goal and streak are shown on the home screen and Progress tab instead — open the app once a day and the streak stays alive. In-app reminders (a banner when your goal is unmet by the evening) are planned; nothing is promised here that is not built.',
  'rb.set.audioSaved': 'تم حفظ صوت الجلسة على هذا الجهاز',
  'rb.set.audioNotSaved': 'صوت الجلسة غير محفوظ',
  'rb.set.privacyLong': 'Everything in this app lives on your device by default: progress, mistakes, goals, recordings. Your voice is processed on this device by the downloaded checker — audio is never uploaded, never sold, never shared. There is no tracking and no advertising, and no account is ever required. If you choose to create an optional account (see “Account” below), only your email address and your progress records (which surahs you have memorised, your goals, bookmarks, test results and settings) are stored online, so your progress follows you to other devices. You can delete your progress on this device, or delete your account and its cloud backup, from that same section. The only other network calls are to fetch Quran text, translations and reciter audio.',
  'rb.set.pauseBetween': 'التوقف بين التكرارات',
  'rb.set.once': 'مرة واحدة',
  'rb.set.timesN': '{n} مرات',
  'rb.set.noPause': 'بدون توقف',
  'rb.set.second1': 'ثانية واحدة',
  'rb.set.secondsN': '{n} ثوانٍ',
