  'rb.set.playbackSpeed': 'سرعة التشغيل',
  'rb.set.wbwHint': 'شغّل مقطع كل كلمة بدوره، مع تمييزها أثناء سماعها — لاستماع بطيء ومتأنٍ.',
  'rb.set.hideMarkersHint': 'أخفِ وريدات نهاية الآيات لاختبار حقيقي للذاكرة.',
  'rb.set.mistakesOn': 'تم إبراز سجل الأخطاء',
  'rb.set.mistakesOff': 'سجل الأخطاء متوقف',
  'rb.set.washHint': 'الكلمات التي أخطأت فيها كثيرًا تظهر بغسلة باستيل خفيفة على الصفحة — الأحمر للأكثر خطأً، وتتلاشى إلى الأخضر كلما أتقنتها.',
  'rb.set.washesVisible': 'تبقى الغسلات ظاهرة عند الإخفاء',
  'rb.set.hiddenStayHidden': 'الكلمات المخفية تبقى مخفية',
  'rb.set.tajweedHintLong': 'لوّن الكلمات حسب قاعدة التجويد المنطبقة (مد، غنة، قلقلة…). للعرض فقط — هذا التطبيق لا يكشف أخطاء التجويد.',
  'rb.set.topicHint': 'Tint each ayah by its topic (Allah & Tawhid, Prophets, Afterlife…) with a legend on the mushaf page. A study aid, not tafsir — every ayah is given one main topic by an automatic mapping.',
  'rb.set.weakWashHint': 'أبقِ غسلات نقاط الضعف ظاهرة حتى أثناء إخفاء الآيات، لترى أين تنتبه قبل أن ترتّل.',
  'rb.set.recordingsHint': 'Keep your own recitation recordings on this device so you can listen back to them. Recordings never leave the device unless you choose to share one, and are never uploaded by the app.',
  'rb.set.recordingNote': 'When recordings are on, a take\'s audio is saved on this device, so you can listen back to any past session and hear your own recitation of a mistake — it is never uploaded anywhere. Turning recordings off stops new ones being saved; Delete audio recordings in Settings → Privacy removes the saved audio without touching your progress.',
  'rb.set.harakatHint': 'On: a word said with the wrong vowel marks counts as a mistake. Off: harakat differences are ignored. This is about vowel marks only — the checker never judges tajweed.',
  'rb.set.retryHint': 'مفعّل: بعد جلسة فيها أخطاء، يجب أن تعيد تلك الكلمات قبل الانتقال إلى الآية التالية. متوقف: يمكنك المتابعة بعد كلمة أُشير إليها خطأً.',
  'rb.set.soundHint': 'شغّل صوتًا (واهتزازًا، على الهواتف) عند انتهاء سؤال الاختبار.',
  'rb.set.shownLang': 'تُعرض في صفحات السور وفي القارئ، باللغة التي تختارها.',
  'rb.set.shownTafsir': 'تُعرض على صفحات السور في عرض التفسير.',
  'rb.set.listenEverywhere': 'يُستخدم لصوت الاستماع في كل مكان — صفحات السور، والتلاوة، والاختبارات.',
  'rb.set.searchReciters': 'ابحث عن القرّاء…',
  'rb.set.noReciters': 'لا يوجد قرّاء يطابقون بحثك.',
  'rb.set.noTafsirs': 'لا يوجد تفسير يطابق بحثك.',
  'rb.set.noTranslations': 'لا توجد ترجمة تطابق بحثك.',
  'rb.set.deleteAudio': 'احذف كل بيانات الصوت',
  'rb.set.deleteAudioNote': 'يحذف كل شيء على هذا الجهاز، بما في ذلك الصوت المحفوظ',
  'rb.set.micPerm': 'يحتاج المدرّب إلى إذن الميكروفون. إذا كان محظورًا، اسمح به من إعدادات موقع المتصفح (أيقونة القفل ← الميكروفون ← السماح).',
  'rb.set.micQuiet': 'رتّل في غرفة هادئة، قريبًا من الميكروفون. الضوضاء وميكروفونات البلوتوث أو السيارة تسبب إشارات خاطئة.',
  'rb.set.micMadd': 'Long madd (stretching a word for 6 counts) is the checker\'s known weak spot — if it flags a correct long stretch, remove the mistake from your history.',
  'rb.set.micOffline': 'The checker works offline once the model has downloaded (about 25 MB, first recitation). Quran text and reciter audio still need a connection unless saved for offline use.',
  'rb.set.micStuck': 'إذا بدا المدرّب عالقًا في آية، انقر «تدرّب دون ميكروفون» وقيّم نفسك بنفسك بدلًا من ذلك — وستُحتسب الجلسة.',
  'rb.set.listenSync': 'These are the same listen settings used on every surah page — change them here or there, they stay in sync. The ayah range is picked on the surah itself.',
  'rb.set.donateNote': 'This app is free forever — no paid tier, no paywall, no ads. If it helps your hifz and you would like to help keep it running, you can donate. Donations are optional and never unlock anything: everything is already free.',
  'rb.set.repeatSpeed': 'كرر {r}× · سرعة {s}×',
