  // Parity repair (2026-11-24): hardcoded-English strings converted to translated keys (i18n pass Part A).
  'chal.howItWorks': 'كيف يعمل: أنشئ تحديًا وشارك رابطه. عندما يفتح عضو رابطك، ينضم تقدّمه إلى عرضك — وعندما يشارك رابطه معك، ينضم تقدّمه إلى عرضك. دون حسابات، دون خادم، دون رفع أي شيء.',
  'chal.leagueFootnote': 'تعمل الدوريات على تحديات المجموعة نفسها دون حساب المذكورة أعلاه: أنشئ تحديًا وشارك رابطه، وتقدّم مجموعتك هو لوحة المتصدرين. لا جوائز موعودة هنا — النقاط والمراكز هي المكافأة.',
  'chal.leagueIntro': 'سباق محدد بوقت نحو الخير: انضم إلى دوري، وحدد هدف حفظ (مثلاً 80 صفحة في 80 يومًا، صفحة في اليوم)، واحصل على خطة يومية حتى الموعد النهائي، واكسب نقاطًا بالتلاوة أو المراجعة. النقاط تصعد بك في لوحة المتصدرين.',
  'chal.ramadanIntro': 'في كل رمضان: اقرأ أو رتّل 90٪ أو أكثر من القرآن خلال الشهر، ويُتبرع بمصحف ورقي باسمك لمسلم محتاج. مصحف واحد لكل شخص. الانضمام مجاني.',
  'chal.ramadanProgressLabel': 'تقدّم تحدي رمضان',
  'chal.ramadanProgressNote': 'القراءة والاستماع والتلاوة كلها تُحتسب؛ والجلسات خارج التطبيق المسجلة في «تقدّمي» تُحتسب أيضًا. تظهر نسبتك الحية هنا بمجرد بدء رمضان — وعند 90٪ تحصل على تأكيد داخل التطبيق بأن مصحفًا سيُتبرع به باسمك.',
  'chal.tplBaqarahGoal': '48 صفحة في 48 يومًا',
  'chal.tplBaqarahName': 'تحدي سورة البقرة',
  'chal.tplBaqarahNote': 'أطول سورة، صفحة في اليوم',
  'chal.tplImranGoal': 'بوتيرتك، مع فريقك',
  'chal.tplImranName': 'فريق سورة آل عمران',
  'chal.tplImranNote': 'احفظوا معًا، وراجعوا معًا',
  'chal.tplRamadanGoal': '80 صفحة في 80 يومًا',
  'chal.tplRamadanName': 'دوري رمضان 1448',
  'chal.tplRamadanNote': 'صفحة في اليوم حتى رمضان',
  'coach.attributionNote': 'نص القرآن والترجمة والصوت عبر Quran.com. صوت تلاوتك لا يغادر جهازك أبدًا إلا إذا اخترت مشاركته مع معلمك. ما زلت تحتاج إلى معلم للتجويد — هذه الأداة تتحقق من الكلمات، لا من التجويد.',
  'coach.couldNotFollow': 'سمعنا صوتك، لكن المدرّب لم يستطع تتبع الكلمات. حاول تقريب الهاتف قليلًا، والتلاوة بصوت أعلى وأبطأ قليلًا، ومنحه ثانية ليبدأ الاستماع قبل الكلمة الأولى — ثم حاول مجددًا.',
