  'coach.micCheckLink': 'فحص الميكروفون',
  'coach.micExplain': 'نحتاج إلى الميكروفون لسماع تلاوتك. يُعالج الصوت على جهازك ولا يُرفع أبدًا. مشاركة تسجيل مع معلمك خيارك دائمًا، بعد الجلسة — لا يُرسل شيء تلقائيًا.',
