  'rb.set.deleteAudio': 'Supprimer toutes les données audio',
  'rb.set.deleteAudioNote': 'Supprime tout sur cet appareil, y compris l’audio enregistré',
  'rb.set.micPerm': 'Le correcteur a besoin de l’autorisation du microphone. S’il est bloqué, autorisez-le dans les paramètres du site du navigateur (icône cadenas → microphone → Autoriser).',
  'rb.set.micQuiet': 'Récitez dans une pièce calme, près du microphone. Le bruit de fond et les microphones Bluetooth ou de voiture provoquent de fausses alertes.',
  'rb.set.micMadd': 'Long madd (stretching a word for 6 counts) is the checker\'s known weak spot — if it flags a correct long stretch, remove the mistake from your history.',
  'rb.set.micOffline': 'The checker works offline once the model has downloaded (about 25 MB, first recitation). Quran text and reciter audio still need a connection unless saved for offline use.',
  'rb.set.micStuck': 'Si le correcteur semble bloqué sur un verset, touchez « S’entraîner sans micro » et auto-évaluez-vous à la place — la séance compte quand même.',
  'rb.set.listenSync': 'These are the same listen settings used on every surah page — change them here or there, they stay in sync. The ayah range is picked on the surah itself.',
  'rb.set.donateNote': 'This app is free forever — no paid tier, no paywall, no ads. If it helps your hifz and you would like to help keep it running, you can donate. Donations are optional and never unlock anything: everything is already free.',
