  'rb.dash.savingNote': 'Saving downloads the text of every surah in the whole Quran plus the main pages, so the coach works in airplane mode. The AI model itself downloads the first time you recite and is cached on this device after that.',
  'rb.dash.progressLives': 'Progress lives only on this device. Download a copy to keep it safe, or import a copy from another device. This is the v1 substitute for accounts. The export includes your bookmarks and group challenges when you have any.',
