  'rb.dash.sessionTest': 'Test — {type}',
  'rb.goals.memorisedOf': '{a} versets sur {b} mémorisés',
  'rb.goals.presetKahfName': 'Sourate Al-Kahf chaque vendredi',
  // Parity repair (2026-11-24): hardcoded-English strings converted to translated keys (i18n pass Part A).
  'chal.howItWorks': 'Comment ça marche : créez un défi et partagez son lien. Quand un membre ouvre votre lien, sa progression rejoint votre vue — et quand il partage son lien en retour, sa progression rejoint la vôtre. Aucun compte, aucun serveur, rien d’envoyé.',
  'chal.leagueFootnote': 'Les ligues fonctionnent sur les mêmes défis de groupe sans compte ci-dessus : créez un défi, partagez son lien, et la progression de votre groupe est le classement. Aucun prix n’est promis ici — les points et les places sont la récompense.',
  'chal.leagueIntro': 'Une course contre la montre vers le bien : rejoignez une ligue, fixez un objectif de mémorisation (par exemple 80 pages en 80 jours, une page par jour), recevez un plan quotidien jusqu’à la date limite, et gagnez des points en récitant ou en révisant. Les points vous font monter au classement.',
  'chal.ramadanIntro': 'Chaque Ramadan : lisez ou récitez 90 % ou plus du Coran pendant le mois, et un mushaf physique sera offert en votre nom à un musulman dans le besoin. Un par personne. Gratuit.',
  'chal.ramadanProgressLabel': 'Progression du défi Ramadan',
  'chal.ramadanProgressNote': 'La lecture, l’écoute et la récitation comptent toutes ; les sessions hors application enregistrées dans « Mes progrès » comptent aussi. Votre pourcentage en direct apparaît ici dès le début de Ramadan — à 90 %, vous recevez une confirmation dans l’application qu’un mushaf sera offert en votre nom.',
  'chal.tplBaqarahGoal': '48 pages en 48 jours',
  'chal.tplBaqarahName': 'Défi Sourate Al-Baqarah',
  'chal.tplBaqarahNote': 'La plus longue sourate, une page par jour',
  'chal.tplImranGoal': 'À votre rythme, en équipe',
  'chal.tplImranName': 'Équipe Sourate Ali ’Imran',
  'chal.tplImranNote': 'Mémorisez ensemble, révisez ensemble',
  'chal.tplRamadanGoal': '80 pages en 80 jours',
  'chal.tplRamadanName': 'Ligue Ramadan 1448',
  'chal.tplRamadanNote': 'Une page par jour jusqu’au Ramadan',
  'coach.attributionNote': 'Texte du Coran, traduction et audio via Quran.com. Votre audio de récitation ne quitte jamais votre appareil, sauf si vous choisissez de le partager avec votre enseignant. Un enseignant reste nécessaire pour le tajweed — cet outil vérifie les mots, pas le tajweed.',
  'coach.couldNotFollow': 'Nous avons entendu votre voix, mais le vérificateur n’a pas pu suivre les mots. Essayez de rapprocher un peu le téléphone, de réciter un peu plus fort et plus lentement, et de lui laisser une seconde pour commencer à écouter avant le premier mot — puis réessayez.',
  'coach.extraSkippedTitle': 'Mots en trop et passages sautés',
  'coach.extraWordHere': 'Mot en trop entendu par ici',
  'coach.followAlongNote': 'Suivi : récitez avec le texte visible et l’application surligne chaque mot au fur et à mesure. Rien n’est jugé, rien n’est consigné comme erreur.',
  'coach.introRecite': 'Écoutez, cachez le verset, puis récitez-le à voix haute. Le vérificateur suit votre récitation mot à mot, sur cet appareil.',
  'coach.listenBackNotSaved': 'Enregistré sur cet appareil uniquement. Il reste ici sauf si vous choisissez de le partager ou de le télécharger ci-dessous — l’application ne l’envoie jamais, et il n’est pas conservé après cette session de navigateur. Activez « {setting} » dans {settings} pour garder les enregistrements plus tard.',
