  'rb.goals.presetKahfName': 'Surah Al-Kahf setiap Jumat',
  // Parity repair (2026-11-24): hardcoded-English strings converted to translated keys (i18n pass Part A).
  'chal.howItWorks': 'Cara kerja: buat tantangan dan bagikan tautannya. Saat anggota membuka tautan Anda, progresnya bergabung ke tampilan Anda — dan saat mereka membagikan tautan mereka kembali, progres mereka bergabung ke tampilan Anda. Tanpa akun, tanpa server, tanpa unggahan.',
  'chal.leagueFootnote': 'Liga berjalan dengan tantangan grup tanpa akun yang sama di atas: buat tantangan, bagikan tautannya, dan progres grup Anda adalah papan peringkatnya. Tidak ada hadiah yang dijanjikan di sini — poin dan peringkat adalah hadiahnya.',
  'chal.leagueIntro': 'Perlombaan berpacu waktu menuju kebaikan: ikuti Liga, tetapkan target hafalan (misalnya 80 halaman dalam 80 hari, satu halaman sehari), dapatkan rencana harian hingga tenggat waktu, dan raih poin dengan membaca atau mengulang. Poin menaikkan Anda di papan peringkat.',
  'chal.ramadanIntro': 'Setiap Ramadan: baca atau bacakan 90% atau lebih Al-Quran selama bulan itu, dan sebuah mushaf fisik akan didonasikan atas nama Anda kepada seorang Muslim yang membutuhkan. Satu per orang. Gratis untuk bergabung.',
  'chal.ramadanProgressLabel': 'Progres tantangan Ramadan',
  'chal.ramadanProgressNote': 'Membaca, mendengarkan, dan membaca semuanya dihitung; sesi di luar aplikasi yang dicatat di Progres Saya juga dihitung. Persentase langsung Anda muncul di sini begitu Ramadan dimulai — pada 90% Anda mendapat konfirmasi di aplikasi bahwa mushaf akan didonasikan atas nama Anda.',
  'chal.tplBaqarahGoal': '48 halaman dalam 48 hari',
  'chal.tplBaqarahName': 'Tantangan Surah Al-Baqarah',
  'chal.tplBaqarahNote': 'Surah terpanjang, satu halaman sehari',
  'chal.tplImranGoal': 'Kecepatan Anda, tim Anda',
  'chal.tplImranName': 'Tim Surah Ali ’Imran',
  'chal.tplImranNote': 'Hafalkan bersama, ulangi bersama',
  'chal.tplRamadanGoal': '80 halaman dalam 80 hari',
  'chal.tplRamadanName': 'Liga Ramadan 1448',
  'chal.tplRamadanNote': 'Satu halaman sehari hingga Ramadan',
  'coach.attributionNote': 'Teks Al-Quran, terjemahan, dan audio melalui Quran.com. Audio bacaan Anda tidak pernah meninggalkan perangkat Anda kecuali Anda memilih untuk membagikannya dengan guru Anda. Guru tetap dibutuhkan untuk tajwid — alat ini memeriksa kata, bukan tajwid.',
  'coach.couldNotFollow': 'Kami mendengar suara Anda, tetapi pemeriksa tidak dapat mengikuti kata-katanya. Coba pegang ponsel sedikit lebih dekat, baca sedikit lebih keras dan lebih pelan, dan beri waktu satu detik untuk mulai mendengarkan sebelum kata pertama — lalu coba lagi.',
  'coach.extraSkippedTitle': 'Kata tambahan & bagian yang dilewati',
  'coach.extraWordHere': 'Kata tambahan terdengar di dekat sini',
  'coach.followAlongNote': 'Ikuti: baca dengan teks terlihat dan aplikasi menyorot setiap kata saat Anda mengucapkannya. Tidak ada yang dinilai, tidak ada yang dicatat sebagai kesalahan.',
  'coach.introRecite': 'Dengarkan, sembunyikan ayatnya, lalu bacakan dengan suara keras. Pemeriksa mengikuti bacaan Anda kata demi kata, di perangkat ini.',
  'coach.listenBackNotSaved': 'Direkam hanya di perangkat ini. Rekaman tetap di sini kecuali Anda memilih untuk membagikan atau mengunduhnya di bawah — aplikasi tidak pernah mengunggahnya, dan rekaman tidak disimpan setelah sesi browser ini. Aktifkan “{setting}” di {settings} untuk menyimpan rekaman untuk nanti.',
  'coach.listenBackSaved': 'Direkam hanya di perangkat ini, dan disimpan di perangkat ini sehingga Anda dapat mendengarkannya kembali nanti dari riwayat sesi Anda. Rekaman tetap di sini kecuali Anda memilih untuk membagikan atau mengunduhnya di bawah — aplikasi tidak pernah mengunggahnya.',
  'coach.micCheckLink': 'pemeriksaan mikrofon',
  'coach.micExplain': 'Kami membutuhkan mikrofon untuk mendengar bacaan Anda. Audio diproses di perangkat Anda dan tidak pernah diunggah. Membagikan rekaman dengan guru Anda selalu pilihan Anda, setelah sesi — tidak ada yang dikirim otomatis.',
  'coach.passageSkippedHere': 'Bagian dilewati di sini',
  'coach.pausedNote': 'Dijeda — pemeriksa tidak mendengarkan. Ketuk “{resume}” untuk melanjutkan pengambilan yang sama.',
  'coach.peekStreakNote': 'Anda mengintip selama percobaan ini, jadi percobaan ini dihitung sebagai kesalahan untuk beruntun Anda.',
  'coach.removeWrongFlagNote': 'Menghapus kata yang salah ditandai akan menghentikan penghitungannya dalam riwayat kesalahan dan skor tes Anda. Anda dapat mengembalikannya dengan membaca ayat itu lagi.',
  'coach.saidDifferently': 'Diucapkan berbeda',
  'coach.selfMarkIntro': 'Dengarkan di atas, baca dari hafalan, lalu tandai setiap kata sendiri: benar, atau kurang tepat. Kata yang ditandai sendiri diberi label demikian di log.',
  'coach.wordOfInAyah': 'Kata {n} dari {total} dalam ayat ini',
