  'rb.set.deleteAllNote': 'Menghapus SEMUA data Hifz Anda di perangkat ini — progres, kesalahan, tujuan, pengaturan, dan rekaman audio yang disimpan. Ini tidak dapat dibatalkan. Ekspor terlebih dahulu jika Anda menginginkan salinan.',
