  'rb.set.deleteAudioRecordings': 'Hapus rekaman audio',
  'rb.set.detectMistakesHint': 'Tandai kata yang salah, tambahan, terlewat, dan dilewati saat Anda membaca. Mati = hanya mengikuti: aplikasi menyorot kata tetapi tidak pernah menilai.',
  'rb.set.indexedDbNoteA': 'Progres juga dicerminkan ke IndexedDB di perangkat ini (dengan migrasi satu kali atas progres Anda yang ada), sehingga tetap ada meskipun localStorage dihapus oleh browser. Sebagai tamu, tidak ada yang pernah dikirim ke server. Jika Anda memilih membuat ',
  'rb.set.indexedDbNoteB': ' opsional, progres Anda juga dicadangkan ke akun Anda sehingga mengikuti Anda ke perangkat lain — dan hanya saat itu.',
  'rb.set.mistakeFeedbackHint': 'Pelatih menandai kata yang salah, tambahan, dan terlewat saat Anda membaca. Mati = hanya mengikuti, tanpa penanda kesalahan.',
  'rb.set.noGoalsForReminder': 'Belum ada tujuan — buat tujuan di halaman Tujuan terlebih dahulu, lalu aktifkan pengingatnya di sini (browser Anda akan meminta izin terlebih dahulu).',
