  // Parity repair (2026-11-24): hardcoded-English strings converted to translated keys (i18n pass Part A).
  'chal.howItWorks': 'Cara ia berfungsi: cipta cabaran dan kongsi pautannya. Apabila ahli membuka pautan anda, kemajuannya menyertai paparan anda — dan apabila mereka berkongsi pautan mereka kembali, kemajuan mereka menyertai paparan anda. Tiada akaun, tiada pelayan, tiada muat naik.',
  'chal.leagueFootnote': 'Liga berjalan dengan cabaran kumpulan tanpa akaun yang sama di atas: cipta cabaran, kongsi pautannya, dan kemajuan kumpulan anda adalah papan pendahulu. Tiada hadiah dijanjikan di sini — mata dan kedudukan adalah ganjarannya.',
  'chal.leagueIntro': 'Perlumbaan bermasa menuju kebaikan: sertai Liga, tetapkan matlamat hafazan (contohnya 80 halaman dalam 80 hari, satu halaman sehari), dapatkan pelan harian sehingga tarikh akhir, dan peroleh mata dengan membaca atau mengulang. Mata menaikkan anda di papan pendahulu.',
  'chal.ramadanIntro': 'Setiap Ramadan: baca atau bacakan 90% atau lebih Al-Quran sepanjang bulan itu, dan sebuah mushaf fizikal akan didermakan atas nama anda kepada seorang Muslim yang memerlukan. Satu bagi setiap orang. Percuma untuk menyertai.',
  'chal.ramadanProgressLabel': 'Kemajuan cabaran Ramadan',
  'chal.ramadanProgressNote': 'Membaca, mendengar dan membacakan semuanya dikira; sesi luar aplikasi yang dilog di Kemajuan Saya juga dikira. Peratusan langsung anda muncul di sini sebaik sahaja Ramadan bermula — pada 90% anda mendapat pengesahan dalam aplikasi bahawa mushaf akan didermakan atas nama anda.',
  'chal.tplBaqarahGoal': '48 halaman dalam 48 hari',
  'chal.tplBaqarahName': 'Cabaran Surah Al-Baqarah',
  'chal.tplBaqarahNote': 'Surah terpanjang, satu halaman sehari',
  'chal.tplImranGoal': 'Rentak anda, pasukan anda',
  'chal.tplImranName': 'Pasukan Surah Ali ’Imran',
  'chal.tplImranNote': 'Hafaz bersama, ulang bersama',
  'chal.tplRamadanGoal': '80 halaman dalam 80 hari',
  'chal.tplRamadanName': 'Liga Ramadan 1448',
  'chal.tplRamadanNote': 'Satu halaman sehari sehingga Ramadan',
  'coach.attributionNote': 'Teks Al-Quran, terjemahan dan audio melalui Quran.com. Audio bacaan anda tidak pernah meninggalkan peranti anda kecuali anda memilih untuk berkongsinya dengan guru anda. Guru masih diperlukan untuk tajwid — alat ini menyemak perkataan, bukan tajwid.',
  'coach.couldNotFollow': 'Kami mendengar suara anda, tetapi pemeriksa tidak dapat mengikuti perkataannya. Cuba pegang telefon sedikit lebih dekat, baca sedikit lebih kuat dan lebih perlahan, dan beri satu saat untuk mula mendengar sebelum perkataan pertama — kemudian cuba lagi.',
  'coach.extraSkippedTitle': 'Perkataan tambahan & bahagian yang dilangkau',
  'coach.extraWordHere': 'Perkataan tambahan didengar berhampiran sini',
  'coach.followAlongNote': 'Ikut serta: baca dengan teks kelihatan dan aplikasi menyerlahkan setiap perkataan semasa anda menyebutnya. Tiada yang dinilai, tiada yang dilog sebagai kesilapan.',
  'coach.introRecite': 'Dengar, sembunyikan ayat, kemudian bacakan dengan kuat. Pemeriksa mengikuti bacaan anda perkataan demi perkataan, di peranti ini.',
  'coach.listenBackNotSaved': 'Dirakam hanya di peranti ini. Ia kekal di sini kecuali anda memilih untuk berkongsi atau memuat turunnya di bawah — aplikasi tidak pernah memuat naiknya, dan ia tidak disimpan selepas sesi pelayar ini. Hidupkan “{setting}” dalam {settings} untuk menyimpan rakaman untuk kemudian.',
  'coach.listenBackSaved': 'Dirakam hanya di peranti ini, dan disimpan di peranti ini supaya anda boleh mendengarnya semula kemudian dari sejarah sesi anda. Ia kekal di sini kecuali anda memilih untuk berkongsi atau memuat turunnya di bawah — aplikasi tidak pernah memuat naiknya.',
  'coach.micCheckLink': 'pemeriksaan mikrofon',
  'coach.micExplain': 'Kami memerlukan mikrofon untuk mendengar bacaan anda. Audio diproses pada peranti anda dan tidak pernah dimuat naik. Berkongsi rakaman dengan guru anda sentiasa pilihan anda, selepas sesi — tiada yang dihantar secara automatik.',
  'coach.passageSkippedHere': 'Bahagian dilangkau di sini',
  'coach.pausedNote': 'Dijeda — pemeriksa tidak mendengar. Ketik “{resume}” untuk meneruskan rakaman yang sama.',
  'coach.peekStreakNote': 'Anda mengintai semasa percubaan ini, jadi ia dikira sebagai kesilapan untuk rentetan anda.',
  'coach.removeWrongFlagNote': 'Mengalih keluar perkataan yang salah ditanda akan menghentikan pengiraannya dalam sejarah kesilapan dan skor ujian anda. Anda boleh mengembalikannya dengan membaca ayat itu semula.',
  'coach.saidDifferently': 'Disebut berbeza',
  'coach.selfMarkIntro': 'Dengar di atas, baca dari hafalan, kemudian tanda setiap perkataan sendiri: betul, atau tidak begitu. Perkataan yang ditanda sendiri dilabel demikian dalam log.',
  'coach.wordOfInAyah': 'Perkataan {n} daripada {total} dalam ayat ini',
