  'ins.mostMissedBody': 'Terlepas {a} {times} ({b} {words} berbeza), masih belum dibetulkan. Jadikan ia ayat pertama dalam pusingan ulang kaji anda yang seterusnya.',
  'ins.mostMissedTitle': 'Ayat paling kerap terlepas: {ref}',
  'ins.noHistoryBody': 'Ambil ujian pertama anda dan panduan anda akan muncul di sini — dibina daripada keputusan dan kesilapan anda sendiri, jadi tiada apa yang ditunjukkan sehingga anda mempunyai beberapa.',
  'ins.noHistoryTitle': 'Belum ada sejarah ujian',
  'ins.nothingMissedBody': 'Anda mempunyai {n} {tests} yang selesai dan tiada kesilapan yang belum dibetulkan — setiap kesilapan setakat ini telah diperbaiki. Uji surah yang belum anda cuba untuk mencari titik lemah yang seterusnya.',
