  'rb.set.deleteAllData': 'Padam semua data',
  'rb.set.deleteAllNote': 'Memadam SEMUA data Hifz anda pada peranti ini — kemajuan, kesilapan, matlamat, tetapan dan rakaman audio yang disimpan. Ini tidak boleh dibuat asal. Eksport dahulu jika anda mahukan salinan.',
  'rb.set.deleteAudioFailed': 'Tidak dapat memadam audio yang disimpan — storan pelayar tidak tersedia. Tiada yang dipadam.',
  'rb.set.deleteAudioOnlyNote': 'Hanya memadam rakaman audio bacaan anda yang disimpan pada peranti ini. Kemajuan, kesilapan, matlamat dan tetapan anda kekal tepat seperti sediakala.',
  'rb.set.deleteAudioRecordings': 'Padam rakaman audio',
  'rb.set.detectMistakesHint': 'Tanda perkataan yang salah, tambahan, terlepas dan dilangkau semasa anda membaca. Mati = ikut serta sahaja: aplikasi menyerlahkan perkataan tetapi tidak pernah menilai.',
  'rb.set.indexedDbNoteA': 'Kemajuan juga dicerminkan ke IndexedDB pada peranti ini (dengan migrasi sekali sahaja bagi kemajuan anda yang sedia ada), jadi ia kekal walaupun localStorage dipadamkan oleh pelayar. Sebagai tetamu, tiada yang pernah dihantar ke pelayan. Jika anda memilih untuk mencipta ',
  'rb.set.indexedDbNoteB': ' pilihan, kemajuan anda juga disandarkan ke akaun anda supaya ia mengikut anda ke peranti lain — dan hanya ketika itu.',
  'rb.set.mistakeFeedbackHint': 'Jurulatih menanda perkataan yang salah, tambahan dan terlepas semasa anda membaca. Mati = ikut serta sahaja, tiada tanda kesilapan.',
  'rb.set.noGoalsForReminder': 'Belum ada matlamat — cipta matlamat di halaman Matlamat dahulu, kemudian hidupkan peringatannya di sini (pelayar anda akan meminta kebenaran dahulu).',
