  'rb.set.remindersBlockedNote': 'Pemberitahuan kini disekat untuk tapak ini dalam tetapan pelayar anda — benarkan di sana sebelum menghidupkan peringatan.',
  'rb.set.remindersLocalNote': 'Peringatan hanya tempatan: aplikasi menunjukkan pemberitahuan pada peranti ini pada masa yang anda pilih. Tiada yang dihantar ke pelayan dan tiada langganan push.',
  'rb.set.streakHomeNote': 'Matlamat harian dan rentetan anda juga ditunjukkan pada skrin utama dan tab Kemajuan — buka aplikasi sekali sehari dan rentetan kekal hidup.',
