  'surah.reciteIntro': 'Dengar, sembunyikan ayat, kemudian bacakan dari hafalan. Pemeriksa mengikuti bacaan anda perkataan demi perkataan, di peranti ini — audio anda tidak pernah meninggalkan peranti anda kecuali anda memilih untuk berkongsinya.',
