  'surah.wbwIntro': 'Perkataan demi perkataan: setiap perkataan dimainkan sendiri dan diserlahkan dalam baris Arab semasa ia berbunyi. Jika ayat tiada audio perkataan, seluruh ayat dimainkan sebagai ganti.',
  'test.aboutAyahsPerQ': 'Kira-kira {n} {ayahs} setiap soalan — ayat yang panjang meliputi lebih banyak baris daripada ayat pendek, jadi ini anggaran.',
