  'rb.set.account': 'Аккаунт',
  'rb.set.noPush': 'Только на устройстве — без push-уведомлений',
  'rb.set.noPushNote': 'The app works fully without an account, so it cannot send push notifications. Your daily goal and streak are shown on the home screen and Progress tab instead — open the app once a day and the streak stays alive. In-app reminders (a banner when your goal is unmet by the evening) are planned; nothing is promised here that is not built.',
  'rb.set.audioSaved': 'Аудио сессии сохранено на этом устройстве',
  'rb.set.audioNotSaved': 'Аудио сессии не сохранено',
  'rb.set.privacyLong': 'Everything in this app lives on your device by default: progress, mistakes, goals, recordings. Your voice is processed on this device by the downloaded checker — audio is never uploaded, never sold, never shared. There is no tracking and no advertising, and no account is ever required. If you choose to create an optional account (see “Account” below), only your email address and your progress records (which surahs you have memorised, your goals, bookmarks, test results and settings) are stored online, so your progress follows you to other devices. You can delete your progress on this device, or delete your account and its cloud backup, from that same section. The only other network calls are to fetch Quran text, translations and reciter audio.',
  'rb.set.pauseBetween': 'Пауза между повторами',
  'rb.set.once': 'Один раз',
  'rb.set.timesN': '{n} раз',
  'rb.set.noPause': 'Без паузы',
  'rb.set.second1': '1 секунда',
  'rb.set.secondsN': '{n} сек.',
  'rb.set.speedNormal': '1× (обычная)',
  'rb.set.playbackSpeed': 'Скорость воспроизведения',
  'rb.set.wbwHint': 'Воспроизводит клип каждого слова по очереди, подсвечивая его во время звучания, — для медленного, внимательного прослушивания.',
  'rb.set.hideMarkersHint': 'Скрывайте розетки в конце аятов для настоящей проверки памяти.',
  'rb.set.mistakesOn': 'История ошибок подсвечена',
  'rb.set.mistakesOff': 'История ошибок отключена',
  'rb.set.washHint': 'Слова, в которых вы часто ошибались, получают мягкую пастельную подсветку на странице: красную — для самых частых ошибок, бледнеющую к зелёной по мере улучшения.',
  'rb.set.washesVisible': 'Подсветка остаётся видимой при скрытии',
  'rb.set.hiddenStayHidden': 'Скрытые слова остаются скрытыми',
  'rb.set.tajweedHintLong': 'Раскрашивает слова по применимому правилу таджвида (мадд, гунна, калькаля…). Только отображение — приложение не определяет ошибки таджвида.',
  'rb.set.topicHint': 'Tint each ayah by its topic (Allah & Tawhid, Prophets, Afterlife…) with a legend on the mushaf page. A study aid, not tafsir — every ayah is given one main topic by an automatic mapping.',
  'rb.set.weakWashHint': 'Держите подсветку слабых мест видимой, даже когда аяты скрыты, чтобы видеть, где быть внимательнее, прежде чем читать.',
  'rb.set.recordingsHint': 'Keep your own recitation recordings on this device so you can listen back to them. Recordings never leave the device unless you choose to share one, and are never uploaded by the app.',
  'rb.set.recordingNote': 'When recordings are on, a take\'s audio is saved on this device, so you can listen back to any past session and hear your own recitation of a mistake — it is never uploaded anywhere. Turning recordings off stops new ones being saved; Delete audio recordings in Settings → Privacy removes the saved audio without touching your progress.',
  'rb.set.harakatHint': 'On: a word said with the wrong vowel marks counts as a mistake. Off: harakat differences are ignored. This is about vowel marks only — the checker never judges tajweed.',
  'rb.set.retryHint': 'Вкл.: после занятия с ошибками вы должны повторить эти слова, прежде чем переходить к следующему аяту. Выкл.: можно идти дальше после неверно отмеченного слова.',
  'rb.set.soundHint': 'Воспроизводить звук (и вибрацию на телефоне), когда завершается вопрос теста.',
  'rb.set.shownLang': 'Показывается на страницах сур и в читалке на выбранном вами языке.',
  'rb.set.shownTafsir': 'Показано на страницах сур в режиме тафсира.',
  'rb.set.listenEverywhere': 'Используется для аудио прослушивания везде — на страницах сур, в чтении и тестах.',
  'rb.set.searchReciters': 'Найти чтеца…',
  'rb.set.noReciters': 'Нет чтецов, соответствующих поиску.',
  'rb.set.noTafsirs': 'Нет тафсиров, соответствующих поиску.',
  'rb.set.noTranslations': 'Нет переводов, соответствующих поиску.',
  'rb.set.deleteAudio': 'Удалить все аудиоданные',
  'rb.set.deleteAudioNote': 'Удаляет всё на этом устройстве, включая сохранённое аудио',
  'rb.set.micPerm': 'Наставнику нужно разрешение на микрофон. Если оно заблокировано, разрешите его в настройках сайта браузера (значок замка → микрофон → Разрешить).',
  'rb.set.micQuiet': 'Читайте в тихой комнате, близко к микрофону. Фоновый шум и микрофоны Bluetooth или автомобильные дают ложные срабатывания.',
  'rb.set.micMadd': 'Long madd (stretching a word for 6 counts) is the checker\'s known weak spot — if it flags a correct long stretch, remove the mistake from your history.',
  'rb.set.micOffline': 'The checker works offline once the model has downloaded (about 25 MB, first recitation). Quran text and reciter audio still need a connection unless saved for offline use.',
  'rb.set.micStuck': 'Если наставник застрял на одном аяте, нажмите «Тренироваться без микрофона» и оценивайте себя сами — занятие всё равно засчитается.',
  'rb.set.listenSync': 'These are the same listen settings used on every surah page — change them here or there, they stay in sync. The ayah range is picked on the surah itself.',
  'rb.set.donateNote': 'This app is free forever — no paid tier, no paywall, no ads. If it helps your hifz and you would like to help keep it running, you can donate. Donations are optional and never unlock anything: everything is already free.',
