  'rb.goals.memorisedOf': '{a} из {b} аятов заучено',
  'rb.goals.presetKahfName': 'Сура Аль-Кахф каждую пятницу',
  // Parity repair (2026-11-24): hardcoded-English strings converted to translated keys (i18n pass Part A).
  'chal.howItWorks': 'Как это работает: создайте испытание и поделитесь его ссылкой. Когда участник откроет вашу ссылку, его прогресс появится в вашем виде — а когда он поделится своей ссылкой в ответ, его прогресс появится у вас. Без учётных записей, без сервера, без загрузок.',
  'chal.leagueFootnote': 'Лиги работают на тех же групповых испытаниях без учётной записи, что и выше: создайте испытание, поделитесь его ссылкой, и прогресс вашей группы станет таблицей лидеров. Призов здесь не обещают — награда в очках и местах.',
  'chal.leagueIntro': 'Гонка на время к добру: вступите в лигу, поставьте цель по заучиванию (например, 80 страниц за 80 дней, страница в день), получайте ежедневный план до крайнего срока и зарабатывайте очки чтением или повторением. Очки поднимают вас в таблице лидеров.',
  'chal.ramadanIntro': 'Каждый Рамадан: прочитайте или прочтите 90% или больше Корана за месяц, и физический мусхаф будет пожертвован от вашего имени нуждающемуся мусульманину. Один на человека. Участие бесплатно.',
  'chal.ramadanProgressLabel': 'Прогресс испытания Рамадана',
  'chal.ramadanProgressNote': 'Чтение, прослушивание и чтение вслух засчитываются; засчитываются и сессии вне приложения, записанные в разделе «Мой прогресс». Ваш текущий процент появится здесь, как только начнётся Рамадан, — при 90% вы получите подтверждение в приложении, что мусхаф будет пожертвован от вашего имени.',
  'chal.tplBaqarahGoal': '48 страниц за 48 дней',
  'chal.tplBaqarahName': 'Испытание «Аль-Бакара»',
  'chal.tplBaqarahNote': 'Самая длинная сура, страница в день',
  'chal.tplImranGoal': 'Ваш темп, ваша команда',
  'chal.tplImranName': 'Команда «Али Имран»',
  'chal.tplImranNote': 'Учите вместе, повторяйте вместе',
  'chal.tplRamadanGoal': '80 страниц за 80 дней',
  'chal.tplRamadanName': 'Лига Рамадана 1448',
  'chal.tplRamadanNote': 'Страница в день до Рамадана',
  'coach.attributionNote': 'Текст Корана, перевод и аудио — через Quran.com. Аудио вашего чтения никогда не покидает ваше устройство, если вы сами не решите поделиться им с учителем. Учитель по-прежнему нужен для таджвида — этот инструмент проверяет слова, а не таджвид.',
  'coach.couldNotFollow': 'Мы слышали ваш голос, но проверяющий не смог проследить слова. Попробуйте держать телефон чуть ближе, читать чуть громче и медленнее и дать ему секунду, чтобы начать слушать до первого слова, — затем попробуйте снова.',
  'coach.extraSkippedTitle': 'Лишние слова и пропущенные отрывки',
  'coach.extraWordHere': 'Рядом здесь услышано лишнее слово',
  'coach.followAlongNote': 'Сопровождение: читайте с видимым текстом, и приложение подсвечивает каждое слово, когда вы его произносите. Ничего не оценивается, ничего не записывается как ошибка.',
  'coach.introRecite': 'Послушайте, скройте аят, затем прочитайте его вслух. Проверяющий следует вашему чтению слово за словом, на этом устройстве.',
  'coach.listenBackNotSaved': 'Записано только на этом устройстве. Запись остаётся здесь, если вы не решите поделиться ею или скачать её ниже, — приложение никогда её не загружает, и она не сохраняется после этой сессии браузера. Включите «{setting}» в разделе {settings}, чтобы сохранять записи на потом.',
  'coach.listenBackSaved': 'Записано только на этом устройстве и сохранено на этом устройстве, чтобы вы могли прослушать запись позже из истории сессий. Запись остаётся здесь, если вы не решите поделиться ею или скачать её ниже, — приложение никогда её не загружает.',
  'coach.micCheckLink': 'проверку микрофона',
  'coach.micExplain': 'Нам нужен микрофон, чтобы слышать ваше чтение. Аудио обрабатывается на вашем устройстве и никогда не загружается. Поделиться записью с учителем — всегда ваш выбор, после сессии: ничего не отправляется автоматически.',
  'coach.passageSkippedHere': 'Отрывок пропущен здесь',
  'coach.pausedNote': 'Пауза — проверяющий не слушает. Нажмите «{resume}», чтобы продолжить ту же попытку.',
  'coach.peekStreakNote': 'Вы подглядели во время этой попытки, поэтому она засчитывается как ошибка для вашей серии.',
  'coach.removeWrongFlagNote': 'Удаление ошибочно отмеченного слова прекращает его учёт в истории ошибок и результатах тестов. Его можно вернуть, прочитав аят ещё раз.',
  'coach.saidDifferently': 'Сказано иначе',
  'coach.selfMarkIntro': 'Послушайте выше, прочитайте по памяти, затем оцените каждое слово сами: верно или не совсем. Слова с самооценкой помечаются так в журнале.',
  'coach.wordOfInAyah': 'Слово {n} из {total} в этом аяте',
