  'rb.set.wbwHint': 'हर शब्द का क्लिप बारी-बारी से चलाएँ, बजते समय उसे उजागर करते हुए — धीमे, ध्यानपूर्वक सुनने के लिए।',
  'rb.set.hideMarkersHint': 'स्मृति की सच्ची जाँच के लिए आयत-अंत के गुलाब चिह्न छिपाएँ।',
  'rb.set.mistakesOn': 'गलती इतिहास हाइलाइट किया गया',
  'rb.set.mistakesOff': 'गलती इतिहास बंद',
  'rb.set.washHint': 'जिन शब्दों में आप अक्सर चूकते हैं वे पृष्ठ पर हल्के पेस्टल रंग में दिखते हैं — सबसे ज़्यादा चुके शब्द लाल, सही होते ही हरे की ओर फीके।',
  'rb.set.washesVisible': 'छिपाने पर भी रंग दिखाई देते रहेंगे',
  'rb.set.hiddenStayHidden': 'छिपे शब्द छिपे रहते हैं',
  'rb.set.tajweedHintLong': 'लागू तजवीद नियम के अनुसार शब्दों को रंगें (मद्द, ग़ुन्ना, क़लक़ला…)। केवल प्रदर्शन — यह ऐप तजवीद गलतियाँ नहीं पहचानता।',
  'rb.set.topicHint': 'Tint each ayah by its topic (Allah & Tawhid, Prophets, Afterlife…) with a legend on the mushaf page. A study aid, not tafsir — every ayah is given one main topic by an automatic mapping.',
  'rb.set.weakWashHint': 'आयतें छिपी हों तब भी कमज़ोर स्थानों के रंग दिखते रहें, ताकि पढ़ने से पहले पता हो कि कहाँ सावधानी चाहिए।',
  'rb.set.recordingsHint': 'Keep your own recitation recordings on this device so you can listen back to them. Recordings never leave the device unless you choose to share one, and are never uploaded by the app.',
  'rb.set.recordingNote': 'When recordings are on, a take\'s audio is saved on this device, so you can listen back to any past session and hear your own recitation of a mistake — it is never uploaded anywhere. Turning recordings off stops new ones being saved; Delete audio recordings in Settings → Privacy removes the saved audio without touching your progress.',
  'rb.set.harakatHint': 'On: a word said with the wrong vowel marks counts as a mistake. Off: harakat differences are ignored. This is about vowel marks only — the checker never judges tajweed.',
  'rb.set.retryHint': 'चालू: गलतियों वाले सत्र के बाद, अगली आयत पर जाने से पहले उन शब्दों को फिर से आज़माना होगा। बंद: गलत चिह्न वाले शब्द के बाद भी आगे बढ़ सकते हैं।',
  'rb.set.soundHint': 'टेस्ट प्रश्न पूरा होने पर ध्वनि बजाएँ (और फ़ोन पर कंपन करें)।',
  'rb.set.shownLang': 'सूरह पृष्ठों और रीडर में, आपकी चुनी भाषा में दिखाया जाता है।',
  'rb.set.shownTafsir': 'तफ़सीर दृश्य में सूरह पृष्ठों पर दिखाया गया।',
  'rb.set.listenEverywhere': 'सुनने के ऑडियो के लिए हर जगह उपयोग होता है — सूरह पृष्ठ, पढ़ना और टेस्ट।',
  'rb.set.searchReciters': 'क़ारी खोजें…',
  'rb.set.noReciters': 'आपकी खोज से कोई क़ारी नहीं मिला।',
  'rb.set.noTafsirs': 'आपकी खोज से कोई तफ़सीर नहीं मिली।',
  'rb.set.noTranslations': 'आपकी खोज से कोई अनुवाद नहीं मिला।',
  'rb.set.deleteAudio': 'सभी ऑडियो डेटा हटाएँ',
  'rb.set.deleteAudioNote': 'इस डिवाइस पर सब कुछ हटाता है, सहेजा गया ऑडियो सहित',
  'rb.set.micPerm': 'कोच को माइक्रोफ़ोन की अनुमति चाहिए। यदि यह अवरुद्ध है, तो अपने ब्राउज़र की साइट सेटिंग्स में अनुमति दें (ताला आइकन → माइक्रोफ़ोन → अनुमति दें)।',
  'rb.set.micQuiet': 'शांत कमरे में, माइक्रोफ़ोन के पास पढ़ें। पृष्ठभूमि शोर और ब्लूटूथ या कार माइक्रोफ़ोन से गलत चिह्न लगते हैं।',
  'rb.set.micMadd': 'Long madd (stretching a word for 6 counts) is the checker\'s known weak spot — if it flags a correct long stretch, remove the mistake from your history.',
  'rb.set.micOffline': 'The checker works offline once the model has downloaded (about 25 MB, first recitation). Quran text and reciter audio still need a connection unless saved for offline use.',
  'rb.set.micStuck': 'यदि कोच किसी आयत पर अटका लगे, तो “बिना माइक अभ्यास करें” पर टैप करें और स्वयं मूल्यांकन करें — सत्र फिर भी गिना जाएगा।',
  'rb.set.listenSync': 'These are the same listen settings used on every surah page — change them here or there, they stay in sync. The ayah range is picked on the surah itself.',
  'rb.set.donateNote': 'This app is free forever — no paid tier, no paywall, no ads. If it helps your hifz and you would like to help keep it running, you can donate. Donations are optional and never unlock anything: everything is already free.',
  'rb.set.repeatSpeed': '{r}× दोहराएँ · {s}× गति',
