  'ins.mostMissedBody': '{a} {times} छूटी ({b} अलग {words}), अभी तक सही नहीं हुई। इसे अपने अगले मुराजअत दौर की पहली आयत बनाएँ।',
  'ins.mostMissedTitle': 'सबसे ज़्यादा छूटी आयत: {ref}',
  'ins.noHistoryBody': 'अपना पहला टेस्ट दें और आपके संकेत यहाँ दिखाई देंगे — आपके अपने परिणामों और छूटों से बने, इसलिए जब तक आपके पास कुछ न हो, दिखाने को कुछ नहीं है।',
  'ins.noHistoryTitle': 'अभी तक कोई टेस्ट इतिहास नहीं',
  'ins.nothingMissedBody': 'आपके {n} पूर्ण {tests} हैं और कोई असही छूट नहीं है — अब तक हर गलती सही कर ली गई है। अगला कमज़ोर स्थान खोजने के लिए ऐसी सूरह टेस्ट करें जो आपने अभी आज़माई न हो।',
  'ins.nothingMissedTitle': 'रिकॉर्ड में कुछ छूटा नहीं',
