  'ins.slippedBody': 'आपके पिछले {n} {tests} का औसत {a}% रहा, जो उससे पहले {b}% था। नीचे दी गई छूटी आयतों की छोटी और अधिक बार-बार मुराजअत उसे वापस ले आएगी।',
  'ins.slippedTitle': 'आपके स्कोर गिर गए हैं',
