  'notif.testReminderBody': 'यह एक टेस्ट रिमाइंडर है — आपके दैनिक रिमाइंडर ऐसे ही दिखेंगे।',
  'notif.testSent': 'टेस्ट रिमाइंडर भेजा गया — यह अभी नोटिफ़िकेशन के रूप में दिखना चाहिए।',
  'notif.turnOnFirst': 'पहले रिमाइंडर चालू करें — आपका ब्राउज़र अनुमति माँगेगा, फिर आप इसे टेस्ट कर सकते हैं।',
  'rb.book.lines15': '15 पंक्तियाँ',
