  'rb.dash.accuracyCaption': 'प्रति सत्र वास्तविक सटीकता (टेस्ट स्कोर + कोच के सही शब्द)। जिन दिनों कोई सत्र न हो वे खाली रहते हैं — कभी भरे नहीं जाते।',
  'rb.dash.accuracyTrend14': 'सटीकता का रुझान — पिछले 14 दिन',
  'rb.dash.accuracyTrendLabel': 'पिछले 14 दिनों में प्रतिदिन वास्तविक सटीकता',
  'rb.dash.addName': 'अपना नाम जोड़ें',
  'rb.dash.addSessionNote': 'ऐप से बाहर पढ़ा या तिलावत की — मुद्रित मुशफ़ से, कक्षा में, उस्ताद के साथ? इसे यहाँ लॉग करें। कोई भी पिछली तारीख़ लॉग की जा सकती है; कल का सत्र छूटे दिन के सिलसिले को बहाल कर देता है, और पुराने दिन सिलसिला बदले बिना आपके इतिहास में रहते हैं।',
